CREATE TABLE DEPLOYMENT (PROJECT TEXT, DEPLOYMENT_ID TEXT, LAST_OPENED TEXT, PROFILE TEXT);
CREATE TABLE FRAMES (PROJECT TEXT, DEPLOYMENT_ID TEXT, FRAME_NUMBER INTEGER, FRAME_TIME TEXT, COMMENT TEXT, ANNOTATOR TEXT, TIME_STAMP TEXT);
CREATE TABLE TARGETS (PROJECT TEXT, DEPLOYMENT_ID TEXT, FRAME_NUMBER INTEGER, TARGET_NUMBER INTEGER, SPECIES_GROUP TEXT, TARGET_LINK INTEGER, COMMENT TEXT, ANNOTATOR TEXT, TIME_STAMP TEXT);
CREATE TABLE POINTS (PROJECT TEXT, DEPLOYMENT_ID TEXT, FRAME_NUMBER INTEGER, TARGET_NUMBER INTEGER, POINT_LABEL TEXT, LX REAL, LY REAL, RX REAL, RY REAL, X REAL, Y REAL, Z REAL, RANGE REAL, ERROR REAL);
CREATE TABLE LINES (PROJECT TEXT, DEPLOYMENT_ID TEXT, FRAME_NUMBER INTEGER, TARGET_NUMBER INTEGER, LINE_LABEL TEXT, LX1 REAL, LY1 REAL, LX2 REAL, LY2 REAL, RX1 REAL, RY1 REAL, RX2 REAL, RY2 REAL, X1 REAL, Y1 REAL, Z1 REAL, X2 REAL, Y2 REAL, Z2 REAL, LENGTH REAL, ERROR REAL);
CREATE TABLE BOUNDING_BOXES (PROJECT TEXT, DEPLOYMENT_ID TEXT, FRAME_NUMBER INTEGER, TARGET_NUMBER INTEGER, SPECIES_GROUP TEXT, CAMERA_ID TEXT, IMAGE_FILE_NAME TEXT, ORIGIN_X REAL, ORIGIN_Y REAL, WIDTH REAL, HEIGHT REAL, FRAME_WIDTH INTEGER, FRAME_HEIGHT INTEGER, ANNOTATOR TEXT);
CREATE TABLE FRAME_METADATA (PROJECT TEXT, DEPLOYMENT_ID TEXT, FRAME_NUMBER INTEGER, METADATA_GROUP TEXT, METADATA_TAG TEXT, METADATA_TYPE TEXT, METADATA_VALUE TEXT, ANNOTATOR TEXT);
